INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_UFO_RELIGION','UFO Religions / Contactee & Channeling Era',1950,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_PARTRIDGE_UFO_RELIGIONS','secondary scholarship','Christopher Partridge (ed.), UFO Religions (London: Routledge, 2003)','Scholarly survey of contactee, channeling, and flying-saucer movements (Raelism, Heaven''s Gate, the Ashtar/Nine channeling milieu, Space Brothers)'),
 ('SRC_LEWIS_GODS_LANDED','secondary scholarship','James R. Lewis (ed.), The Gods Have Landed: New Religions from Other Worlds (Albany: SUNY Press, 1995)','Edited volume on UFO new religious movements, contactee theology, and extraterrestrial salvation narratives')
INSERT INTO _e VALUES
 ('ENT_UFO_PANTHEON','The Powers of the UFO Religions (collective)','collective','pantheon-hub','UFO Religion','extraterrestrial salvation; cosmic guidance; creation','C','Hub collective grouping the benevolent extraterrestrial powers venerated or believed-in across practiced UFO religions (Raelism, Heaven''s Gate, the contactee/channeling milieu). Modeled neutrally as the beings sincerely held to exist within these traditions.'),
 ('ENT_UFO_SPACE_BROTHERS','The Space Brothers','collective','extraterrestrial-beings','UFO Religion','benevolent guidance; cosmic warning; uplift of humanity','B','The benevolent, spiritually advanced extraterrestrials of the 1950s contactee movement (Adamski, Van Tassel, etc.); believed by contactees and channelers to deliver messages of peace and warning. Sincerely held within the contactee/channeling milieu.'),
 ('ENT_UFO_ASHTAR','Ashtar (Ashtar Galactic Command)','being','channeled-extraterrestrial','UFO Religion','galactic command; cosmic guardianship; channeled guidance','B','The extraterrestrial commander first channeled by George Van Tassel (1952) and central to the ongoing Ashtar channeling current; head of the Ashtar Galactic Command. Held to exist and actively channeled within the milieu. NOTE homonym: unrelated to the Moabite Ashtar-Kemosh (ENT_MOA_ASHTAR_KEMOSH).'),
 ('ENT_UFO_COUNCIL_NINE','The Council of Nine ("the Nine" / "Tom")','collective','channeled-beings','UFO Religion','cosmic governance; channeled wisdom; creation oversight','B','Nine cosmic beings (spokesman ''Tom'') channeled through the Andrija Puharich circle from the 1950s onward; influential across the channeling milieu and sincerely received as higher intelligences. Modeled neutrally as beliefs held within the tradition.'),
 ('ENT_UFO_ELOHIM','The Raelian Elohim','collective','extraterrestrial-creators','UFO Religion','creation of humanity by genetic engineering; future return','B','The extraterrestrial creators of the active Raelian movement, held to have engineered humanity in their laboratories; ''Elohim'' read as ''those who came from the sky.'' Core sincerely-held belief of practicing Raelians. NOTE homonym: distinct from Hebrew/Jewish/LDS Elohim (ENT_ISR_BENE_ELOHIM / ENT_JM_ELOHIM_RANK / ENT_LDS_ELOHIM).'),
 ('ENT_UFO_SANANDA','Sananda','being','channeled-extraterrestrial','UFO Religion','cosmic salvation; channeled teaching; ascension','B','The channeled ''cosmic Jesus'' of the Ashtar/I AM-adjacent channeling current, presented as the higher self/galactic identity of Jesus; sincerely received and channeled within the milieu.'),
 ('ENT_UFO_NEXT_LEVEL','The Next Level (Heaven''s Gate)','concept','cosmology','UFO Religion','evolutionary level above human; extraterrestrial kingdom','B','Heaven''s Gate''s term for ''The Evolutionary Level Above Human,'' the extraterrestrial kingdom to which members believed they would graduate; sincerely lived belief of the Heaven''s Gate community.'),
 ('ENT_UFO_TI_DO','Ti and Do (Bonnie Nettles & Marshall Applewhite)','figure','founder-figures','UFO Religion','leadership; Next-Level representatives','B','Co-founders of Heaven''s Gate, believed by members to be incarnated representatives of the Next Level (Do also identified with the returned Jesus-soul). Sincerely venerated as guides by the community. Modeled neutrally.');
